const promptTranslations: Record<string, { ca: string; en: string }> = {};
for (const [source, ca, en] of rows) promptTranslations[source] = { ca, en };

export function translatePrompt(language: 'ca' | 'es' | 'en', value: string): string {
  if (!value || language === 'es') return value;
  const names: string[] = [];
  const key = value.replace(/\|\|\|([^|]+)\|\|\|/g, (_match, name) => {
    names.push(name);
    return '[Player]';
  });
  const translated = promptTranslations[key]?.[language] ?? key;
  let index = 0;
  return translated.replace(/\[Player\]/g, () => names[index++] ?? '[Player]');
}

export const promptTranslationCount = Object.keys(promptTranslations).length;
